class Diagnostic(CommonPage):
    """
    The class corresponding to diagnostic page on selenium_coam web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self):
        if not self._instance_dict:
            self._instance_dict = {"Test Clocks": TestClocksPage(),
                                   "IP Connectivity Test": IPConnectivityTestPage(),
                                   "5G Downlink": TestModels5GDownlinkPage(),
                                   "5G Uplink": TestModels5GUplinkPage(),
                                   "Snapshot": SnapshotPage(),
                                   "PMTU Discovery": PmtuDiscoveryPage(),
                                   "Reset to Test Dedicated State": ResetToTestDedicatedStatePage(),
                                   "Debug Tracing": DebugTracingPage()}
        super(Diagnostic, self).__init__(self._instance_dict)


class IPConnectivityTestPage(object):
    MENU_ROUTE_LIST = ['Diagnostic', 'IP Connectivity Test']

    def __init__(self):
        self._view_panel = IPConnectivityTestPageViewPanel()

    def start_ip_connectivity_test(self, scope, address=None, source_address=None, payload_size=16,
                                   dscp=10, timeout=10):
        """
        Keyword for starting ip connectivity test
        :param scope: str, scope value, default is None
        :param address: str, address value, default is None
        :param source_address: str, source address value, default is None
        :param payload_size: int, payload size, default is 16
        :param dscp: int, dscp value, default is 10
        :param timeout: int, timeout
        """
        self._view_panel.start_ip_connectivity_test(scope, address, source_address, payload_size, dscp, timeout)

    def stop_ip_connectivity_test(self, timeout=10):
        """
        Keyword for stopping ip connectivity test, should never be called before start ip connectivity test
        :param timeout: int, timeout
        """
        self._view_panel.stop_ip_connectivity_test(timeout)


class IPConnectivityTestPageViewPanel(ViewPanel):
    _SCOPE_DROPDOWN_LIST_BUTTON_XPATH = '//label[contains(text(), "Scope")]/parent::*//button'
    _SCOPE_DROPDOWN_LIST_OPTIONS_XPATH = '//label[contains(text(), "Scope")]/parent::*//ul//li'
    _ADDRESS_INPUT_XPATH = '//label[contains(text(), "Address")]/parent::*//input'
    _SOURCE_ADDERSS_BUTTON_XPATH = '//label[contains(text(), "Source address")]/parent::*//button'
    _SOURCE_ADDERSS_OPTIONS_XPATH = '//label[contains(text(), "Source address")]/parent::*//ul//li'
    _PALOAD_SIZE_INPUT_XPATH = '//label[contains(text(), "Payload size")]/parent::*//input'
    _DSCP_INPUT_XPATH = '//label[contains(text(), "DSCP")]/parent::*//input'
    _START_BUTTON_XPATH = '//ip-connectivity-info-table//ui-button[contains(*, "Start")]'
    _STOP_BUTTON_XPATH = '//ip-connectivity-info-table//ui-button[contains(*, "Stop")]'

    def _input_address(self, address, timeout=10):
        if address:
            try:
                self.insert_text_to_enable_element((By.XPATH, self._ADDRESS_INPUT_XPATH), address, timeout)
            except TimeoutException:
                logging.error('Address does not support input now')
                raise

    def _select_source_address(self, source_address, timeout=10):
        if source_address:
            try:
                self.select_element_from_dropdown_list_by_text_and_click(
                    source_address,
                    (By.XPATH, self._SOURCE_ADDERSS_BUTTON_XPATH),
                    (By.XPATH, self._SOURCE_ADDERSS_OPTIONS_XPATH),
                    timeout
                )
            except TimeoutException:
                logging.error('Source address is unclickable now')
                raise

    def start_ip_connectivity_test(self, scope, address=None, source_address=None, payload_size=16,
                                   dscp=10, timeout=10):
        """
        Keyword for starting ip connectivity test
        """
        self.select_element_from_dropdown_list_by_text_and_click(
            scope,
            (By.XPATH, self._SCOPE_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._SCOPE_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )
        self._input_address(address, timeout)
        self._select_source_address(source_address, timeout)
        self.insert_text_to_enable_element((By.XPATH, self._PALOAD_SIZE_INPUT_XPATH), payload_size, timeout)
        self.insert_text_to_enable_element((By.XPATH, self._DSCP_INPUT_XPATH), dscp, timeout)

        self.click_enabled_element((By.XPATH, self._START_BUTTON_XPATH), timeout)

    def stop_ip_connectivity_test(self, timeout=10):
        """
        Keyword for stopping ip connectivity test, should never be called before start ip connectivity test
        """
        self.click_enabled_element((By.XPATH, self._STOP_BUTTON_XPATH), timeout)


class TestModels5GDownlinkPage(object):
    MENU_ROUTE_LIST = ['Diagnostic', 'Test Models', '5G Downlink']

    def __init__(self):
        self._view_panel = TestModels5GDownlinkPageViewPanel()

    def start_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id):
        """
        Starts 5G downlink test.
        :param local_cell: name of local cell for which test will be started
        :type local_cell: str
        :param test_model: name of test model which will be used during test
        :type test_model: str
        :param p_max: value of pMax which will be used during test
        :type p_max: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :param polarization: value of Polarization which will be used during test
        :type polarization: str
        :param physical_cell_id: value of Physical cell ID which will be used during test
        :type physical_cell_id: int
        """
        self._view_panel.start_test(local_cell, test_model, p_max, timeout, polarization, physical_cell_id)

    def wait_for_test_to_start(self, test_id, timeout):
        """
        Waits for test to be successfully started.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._view_panel.wait_for_test_to_start(test_id, timeout)

    def stop_test(self, test_id, timeout):
        """
        Stops 5G downlink test.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._view_panel.stop_test(test_id, timeout)

    def wait_for_test_to_stop(self, test_id, timeout):
        """
        Waits for test to be successfully stopped.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._view_panel.wait_for_test_to_stop(test_id, timeout)

    def get_carrier_frequency(self, timeout):
        """
        Gets value of carrier frequency.
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: value of carrier frequency if is available, None otherwise
        :rtype: float
        """
        return self._view_panel.get_carrier_frequency(timeout)

    def save_test_results(self, test_id, external_equipment_result, timeout):
        """
        Saves results of 5G downlink test.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param external_equipment_result: text which will be typed into 'Test result from external measuring equipment'
                                          before saving test results
        :type external_equipment_result: str
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._view_panel.save_test_results(test_id, external_equipment_result, timeout)

    def is_test_available(self, local_cell, test_model, timeout):
        """
        Checks whether test is visible in Tests table.
        :param local_cell: name of local cell which checked test should contain
        :type local_cell: str
        :param test_model: name of test model which checked test should contain
        :type test_model: str
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: True if test with given local cell and test model is available, False otherwise
        :rtype: bool
        """
        return self._view_panel.is_test_available(local_cell, test_model, timeout)


