class TestModelsPageViewPanel(ViewPanel):
    _LOCAL_CELL_DROPDOWN_LIST_BUTTON_XPATH = '//div[contains(text(), "Local cell:")]/parent::*//button'
    _LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Local cell:")]/parent::*//ul//li'
    _PHYSICAL_CELL_ID_INPUT_XPATH = '//div[contains(text(), "Physical cell ID:")]/parent::*//input'
    _START_TEST_BUTTON_XPATH = '//button[contains(text(), "Start Test")]'
    _STOP_TEST_BUTTON_XPATH = '//div[contains(text(), "Tests")]/parent::*/parent::*//tr[{}]//ui-button'
    _CARRIER_FREQUENCY_VALUE_LABEL_XPATH = '//div[contains(text(), "Carrier frequency:")]/parent::*//span'
    _TESTS_TABLE_ROW_XPATH = '//div[contains(text(), "Tests")]/parent::*/parent::*//tr[{}]/td[1]'
    _TEST_TABLE_PROGRESS_CELL_XPATH = '//div[contains(text(), "Tests")]/parent::*/parent::*//tr[{}]/td[3]'
    _SAVE_TEST_RESULTS_BUTTON_XPATH = '//button[contains(text(), "Save Test Results")]'

    def wait_for_test_to_start(self, test_id, timeout):
        """
        Waits for test to be successfully started.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._check_test_id(test_id)
        self.wait_for_text_present_in_element((By.XPATH, self._TEST_TABLE_PROGRESS_CELL_XPATH.format(test_id)),
                                              'Start test succeed and test is ongoing.', timeout)

    def stop_test(self, test_id, timeout):
        """
        Stops 5G downlink test.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._check_test_id(test_id)
        self.click_enabled_element_after_visible((By.XPATH, self._STOP_TEST_BUTTON_XPATH.format(test_id)), timeout)

    def wait_for_test_to_stop(self, test_id, timeout):
        """
        Waits for test to be successfully stopped.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._check_test_id(test_id)
        self.wait_for_text_present_in_element((By.XPATH, self._TEST_TABLE_PROGRESS_CELL_XPATH.format(test_id)),
                                              'Stop succeed.', timeout)

    def get_carrier_frequency(self, timeout):
        """
        Gets value of carrier frequency.
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: value of carrier frequency if is available, None otherwise
        :rtype: float
        """
        carrier_freq = self.get_text_by_xpath(self._CARRIER_FREQUENCY_VALUE_LABEL_XPATH, timeout)
        carrier_freq = carrier_freq.split(' ')[0]
        carrier_freq = carrier_freq.replace(',', '')
        return float(carrier_freq) if carrier_freq else None

    @staticmethod
    def _check_test_id(test_id):
        if test_id < 1:
            raise ValueError("Test ID can't be lower then 1 but it was {}".format(test_id))

    def _select_test_from_table(self, test_id, timeout):
        self._check_test_id(test_id)
        self.click_enabled_element_after_visible((By.XPATH, self._TESTS_TABLE_ROW_XPATH.format(test_id)), timeout)


class TestModels5GDownlinkPageViewPanel(TestModelsPageViewPanel):
    _TEST_MODEL_DROPDOWN_LIST_BUTTON_XPATH = '//div[contains(text(), "Test model:")]/parent::*//button'
    _TEST_MODEL_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Test model:")]/parent::*//ul//li'
    _POLARIZATION_DROPDOWN_LIST_BUTTON_XPATH = '//div[contains(text(), "Polarization:")]/parent::*//button'
    _POLARIZATION_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Polarization:")]/parent::*//ul//li'
    _P_MAX_INPUT_XPATH = '//div[contains(text(), "pMax:")]/parent::*//input'
    _TESTS_TABLE_ROW_BY_CELL_AND_MODEL_XPATH = \
        '//div[contains(text(), "Tests")]/parent::*/parent::*//td[text()="{}"]/parent::*//td[text()="{}"]'
    _EXTERNAL_EQUIPMENT_RESULT_INPUT_XPATH = \
        '//p[contains(text(), "Test result from external measuring equipment")]/parent::*//textarea'

    def start_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id):
        """
        Starts 5G downlink test.
        :param local_cell: name of local cell for which test will be started
        :type local_cell: str
        :param test_model: name of test model which will be used during test
        :type test_model: str
        :param p_max: value of pMax which will be used during test
        :type p_max: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :param polarization: value of Polarization which will be used during test
        :type polarization: str
        :param physical_cell_id: value of Physical cell ID which will be used during test
        :type physical_cell_id: int
        """
        self.select_element_from_dropdown_list_by_text_and_click(
            local_cell,
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )

        self.select_element_from_dropdown_list_by_text_and_click(
            test_model,
            (By.XPATH, self._TEST_MODEL_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._TEST_MODEL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )

        if polarization is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                polarization,
                (By.XPATH, self._POLARIZATION_DROPDOWN_LIST_BUTTON_XPATH),
                (By.XPATH, self._POLARIZATION_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout
            )

        self.insert_text_to_enable_element((By.XPATH, self._P_MAX_INPUT_XPATH), str(p_max), timeout)

        if physical_cell_id is not None:
            self.insert_text_to_enable_element((By.XPATH, self._PHYSICAL_CELL_ID_INPUT_XPATH), str(physical_cell_id),
                                               timeout)

        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)

    def save_test_results(self, test_id, external_equipment_result, timeout):
        """
        Saves results of 5G downlink test.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param external_equipment_result: text which will be typed into 'Test result from external measuring equipment'
                                          before saving test results
        :type external_equipment_result: str
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._select_test_from_table(test_id, timeout)
        if external_equipment_result:
            self.insert_text_to_enable_element((By.XPATH, self._EXTERNAL_EQUIPMENT_RESULT_INPUT_XPATH),
                                               external_equipment_result, timeout)
            time.sleep(1)
        self.click_enabled_element((By.XPATH, self._SAVE_TEST_RESULTS_BUTTON_XPATH), timeout)

    def is_test_available(self, local_cell, test_model, timeout):
        """
        Checks whether test is visible in Tests table.
        :param local_cell: name of local cell which checked test should contain
        :type local_cell: str
        :param test_model: name of test model which checked test should contain
        :type test_model: str
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: True if test with given local cell and test model is available, False otherwise
        :rtype: bool
        """
        try:
            self.wait_for_visibility_by_xpath(
                self._TESTS_TABLE_ROW_BY_CELL_AND_MODEL_XPATH.format(local_cell.split('-')[1], test_model), timeout)
        except TimeoutException:
            return False
        return True


class TestModels5GUplinkPageViewPanel(TestModelsPageViewPanel):
    _FRC_INDEX_DROPDOWN_LIST_BUTTON_XPATH = '//div[contains(text(), "FRC index:")]/parent::*//button'
    _FRC_INDEX_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "FRC index:")]/parent::*//ul//li'
    _REPORTING_TIME_INTERVAL_INPUT_XPATH = '//div[contains(text(), "Reporting time interval:")]/parent::*//input'
    _TESTS_TABLE_ROW_BY_CELL_AND_FRC_XPATH = \
        '//div[contains(text(), "Tests")]/parent::*/parent::*//td[text()="{}"]/parent::*//td[text()="{}"]'
    _TEST_PARAMETERS_TABLE_XPATH = '//p[contains(text(), "Test parameters")]/parent::*//table'
    _CUMULATIVE_RESULTS_TABLE_XPATH = '//p[contains(text(), "Cumulative results")]/parent::*//table'
    _PARTIAL_RESULTS_TABLE_XPATH = '//p[contains(text(), "Partial results")]/parent::*//table'

    def start_test(self, local_cell, frc_index, reporting_time_interval, timeout, physical_cell_id):
        """
        Starts 5G uplink test.
        :param local_cell: name of local cell for which test will be started
        :type local_cell: str
        :param frc_index: name of test model which will be used during test
        :type frc_index: str
        :param reporting_time_interval: value of Reporting time interval which will be used during test
        :type reporting_time_interval: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :param physical_cell_id: value of Physical cell ID which will be used during test
        :type physical_cell_id: int
        """
        self.select_element_from_dropdown_list_by_text_and_click(
            local_cell,
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._LOCAL_CELL_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )
        self.select_element_from_dropdown_list_by_text_and_click(
            frc_index,
            (By.XPATH, self._FRC_INDEX_DROPDOWN_LIST_BUTTON_XPATH),
            (By.XPATH, self._FRC_INDEX_DROPDOWN_LIST_OPTIONS_XPATH),
            timeout
        )
        self.insert_text_to_enable_element((By.XPATH, self._REPORTING_TIME_INTERVAL_INPUT_XPATH),
                                           str(reporting_time_interval), timeout)

        if physical_cell_id is not None:
            self.insert_text_to_enable_element((By.XPATH, self._PHYSICAL_CELL_ID_INPUT_XPATH), str(physical_cell_id),
                                               timeout)

        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)

    def get_test_parameters_table(self, test_id, timeout):
        """
        Gets whole Test parameters table.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: Dictionary with column names as keys and cell values as lists
        :rtype: {str: [str, ]}
        """
        self._select_test_from_table(test_id, timeout)
        self.wait_for_visibility((By.XPATH, self._TEST_PARAMETERS_TABLE_XPATH), timeout)
        table = HTMLTable(self.driver, self._TEST_PARAMETERS_TABLE_XPATH)
        return table.get_table()

    def get_cumulative_results_table(self, test_id, timeout):
        """
        Gets whole Cumulative results table.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: Dictionary with column names as keys and cell values as lists
        :rtype: {str: [str, ]}
        """
        self._select_test_from_table(test_id, timeout)
        self.wait_for_visibility((By.XPATH, self._CUMULATIVE_RESULTS_TABLE_XPATH), timeout)
        table = HTMLTable(self.driver, self._CUMULATIVE_RESULTS_TABLE_XPATH)
        return table.get_table()

    def get_partial_results_table(self, test_id, timeout):
        """
        Gets whole Partial results table.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: Dictionary with column names as keys and cell values as lists
        :rtype: {str: [str, ]}
        """
        self._select_test_from_table(test_id, timeout)
        self.wait_for_visibility((By.XPATH, self._PARTIAL_RESULTS_TABLE_XPATH), timeout)
        table = HTMLTable(self.driver, self._PARTIAL_RESULTS_TABLE_XPATH)
        return table.get_table()

    def save_test_results(self, test_id, timeout):
        """
        Saves results of 5G uplink test.
        :param test_id: order number of test in Tests table
        :type test_id: int
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        """
        self._select_test_from_table(test_id, timeout)
        self.click_enabled_element((By.XPATH, self._SAVE_TEST_RESULTS_BUTTON_XPATH), timeout)

    def is_test_available(self, local_cell, frc_index, timeout):
        """
        Checks whether test is visible in Tests table.
        :param local_cell: name of local cell which checked test should contain
        :type local_cell: str
        :param frc_index: name of test model which checked test should contain
        :type frc_index: str
        :param timeout: time to wait for individual steps of this operation to be completed
        :type timeout: int
        :return: True if test with given local cell and test model is available, False otherwise
        :rtype: bool
        """
        try:
            self.wait_for_visibility_by_xpath(
                self._TESTS_TABLE_ROW_BY_CELL_AND_FRC_XPATH.format(local_cell.split('-')[1], frc_index), timeout)
        except TimeoutException:
            return False
        return True


