class SnapshotPageViewPanel(ViewPanel):
    _SNAPSHOT_SPINNER_XPATH = "//*[@class ='status-info ng-binding']"
    _SENDING_REQUEST_XPATH = "//label[contains(text(), 'Sending request...')]"
    _COLLECTING_FILES_XPATH = "//label[contains(text(), 'Collecting files...')]"
    _COLLECTION_COMPLETED_XPATH = "//label[contains(text(), 'Collection completed')]"
    _CANCELING_COLLECTION_XPATH = "//label[contains(text(), 'Canceling collection...')]"
    _COLLECTION_CANCELED_XPATH = "//label[contains(text(), 'Collection canceled')]"
    _LOCAL_RADIOBOX_SELECTED_XPATH = "//*[@class='radio radio-small']//*[contains(text(), 'Local')]/../input"
    _COLLECT_SNAPSHOT_BUTTON_XPATH = "//*[@class='snapshot-control-buttons']//button"
    _CANCEL_SNAPSHOT_BUTTON_XPATH = "//*[@class='snapshot-scrollbar-group']//button"

    def set_snapshot_collection_with_radiobox(self, setting_list):
        for elem in setting_list:
            elem_xpath = "//*[@class='radio radio-small']//*[contains(text(), '{}')]".format(elem)
            self.select_radiobox_by_xpath(elem_xpath)

    def _try_collect_snapshot(self, snapshot_waiting_timeout):
        self.click_enabled_element((By.XPATH, self._COLLECT_SNAPSHOT_BUTTON_XPATH))
        try:
            self.wait_for_visibility_by_xpath(self._SENDING_REQUEST_XPATH, snapshot_waiting_timeout)
            self.wait_for_visibility_by_xpath(self._COLLECTING_FILES_XPATH, snapshot_waiting_timeout)
            self.wait_for_visibility_by_xpath(self._COLLECTION_COMPLETED_XPATH, snapshot_waiting_timeout)
            return "Collect Snapshot Finished"
        except TimeoutException:
            error_text = self.get_text_by_xpath(self._SNAPSHOT_SPINNER_XPATH)
            if error_text:
                return error_text
            raise

    def collect_snapshot(self, snapshot_waiting_timeout):
        if self.driver.find_element_by_xpath(self._LOCAL_RADIOBOX_SELECTED_XPATH).is_selected():
            start_time = time.time()
            if self._try_collect_snapshot(snapshot_waiting_timeout) != "Collect Snapshot Finished":
                return "Collect Snapshot Failed"
            return self.download_files(start_time, snapshot_waiting_timeout)
        else:
            return self._try_collect_snapshot(snapshot_waiting_timeout)

    def cancel_collect_snapshot(self, snapshot_waiting_timeout):
        self.click_enabled_element((By.XPATH, self._CANCEL_SNAPSHOT_BUTTON_XPATH))
        try:
            self.wait_for_visibility_by_xpath(self._CANCELING_COLLECTION_XPATH, snapshot_waiting_timeout)
            self.wait_for_visibility_by_xpath(self._COLLECTION_CANCELED_XPATH, snapshot_waiting_timeout)
            return 'Snapshot Collection Canceled Successfully'
        except TimeoutException:
            error_text = self.get_text_by_xpath(self._SNAPSHOT_SPINNER_XPATH)
            if error_text:
                return error_text
            raise


