class TestClocksPageViewPanel(ViewPanel):
    _TEST_CLOCKS_CHECKBOX_XPATH = '//div[@class="testClocks"]//div[@class="test-clocks-checkbox"]//label'
    _TEST_CLOCKS_CHECKBOX_INPUT_XPATH = '//div[@class="testClocks"]//div[@class="test-clocks-checkbox"]//input'
    _TEST_CLOCKS_DATA_SEND_BUTTON_XPATH = '//div[@class="testClocks"]//test-clocks-send-data//button'
    _TEST_CLOCKS_STATE_CHANGE_INFO_XPATH = '//test-clocks-send-data//span[@class="ng-binding"]'
    _TEST_CLOCKS_STATE_CHANGE_INFO = "completed"
    _TEST_CLOCKS_STATUS = '//input[@id="test-clock-state"]'
    _TEST_CLOCKS_STATUS_FLAG = 'not-empty'

    def _change_test_clock_status(self, enable):
        """
        Method for clicking enable button
        :return:
        """
        checkbox_status = self._TEST_CLOCKS_STATUS_FLAG in self.get_attribute_by_xpath(
            self._TEST_CLOCKS_CHECKBOX_INPUT_XPATH, 'class')
        if checkbox_status and enable:
            logging.warning("test clock is already enable")
            return
        elif not checkbox_status and not enable:
            logging.warning("test clock is already disable")
            return
        self.driver.find_element_by_xpath(self._TEST_CLOCKS_CHECKBOX_XPATH).click()

    def _send_test_clocks_data(self, timeout=5):
        """
        Method for clicking send button
        """
        self.click_enabled_element_after_visible((By.XPATH, self._TEST_CLOCKS_DATA_SEND_BUTTON_XPATH), timeout)

    def _get_test_clocks_state_change_info(self, timeout=30):
        """
        Method for get changed state of test clocks
        """
        if self.check_if_element_has_text((By.XPATH, self._TEST_CLOCKS_STATE_CHANGE_INFO_XPATH),
                                          self._TEST_CLOCKS_STATE_CHANGE_INFO, timeout):
            return "Test clock state change completed"
        return "Test clock state change failed"

    def enable_test_clock_for_rap_and_return_outcome(self, timeout=30):
        """
        Method for enabling test clocks for rap in 'Test Clocks' page
        """
        self._change_test_clock_status(True)
        self._send_test_clocks_data()
        return self._get_test_clocks_state_change_info(timeout)

    def disable_test_clock_for_rap_and_return_outcome(self, timeout=30):
        """
        Method for disable test clocks for rap in 'Test Clocks' page
        """
        self._change_test_clock_status(False)
        self._send_test_clocks_data()
        return self._get_test_clocks_state_change_info(timeout)

    def get_test_clock_status(self):
        """
        Method for get status of test clock
        """
        return self.get_attribute_by_xpath(self._TEST_CLOCKS_STATUS, "value")


