    _RLC_RADIO_BOX_XPATH = '//section[@class="uPlane-component"]//input[contains(@id, "rlc")]/../label'
    _CELLS_BUTTON_XPATH = '//{}//cells-component/ui-select[{}]//button'
    _CELLS_OPTION_XPATH = '//{}//cells-component/ui-select[{}]//ul//span'
    _START_TRACE_BUTTON_XPATH = '//section[@class="uPlane-component"]//ui-button[@*="Start Traces"]//button'
    _STOP_TRACE_BUTTON_XPATH = '//section[@class="uPlane-component"]//ui-button[@*="Stop Traces"]//button'
    _COMPONENT_TRACE_STATUS_XPATH = '//u-plane-component//*[contains(@class, "tracing-progress-message")]' \
                                    '//span[not(contains(@class, "icon"))]'
    _UPLANE_SHERPA_BASE_XPATH = '//u-plane-sherpa//span[text()="{}"]'
    _SHERPA_L2_HI_XPATH = _UPLANE_SHERPA_BASE_XPATH.format('L2-HI')
    _SHERPA_L2_LO_XPATH = _UPLANE_SHERPA_BASE_XPATH.format('L2-LO')
    _SHERPA_L2_PS_XPATH = _UPLANE_SHERPA_BASE_XPATH.format('L2-PS')
    _SHERPA_PDCP_RADIO_BOX_XPATH = '//u-plane-sherpa//input[contains(@id, "sherpaPdcp")]/../label'
    _SHERPA_RLC_RADIO_BOX_XPATH = '//u-plane-sherpa//input[contains(@id, "sherpaRlc")]/../label'
    _SHERPA_START_TRACES_BUTTON_XPATH = '//u-plane-sherpa//ui-button[@*="Start Traces"]//button'
    _SHERPA_STOP_TRACES_BUTTON_XPATH = '//u-plane-sherpa//ui-button[@*="Stop Traces"]//button'
    _SHERPA_TRACE_STATUS_XPATH = '//u-plane-sherpa//*[contains(@class, "tracing-progress-message") ' \
                                 'or @class="debug-setup-control"]//span[not(contains(@class, "icon"))]'

    _CPLANE_START_DU_TRACES_BUTTON_XPATH = '//cplane//ui-button' \
                                           '[@a-text="Start DU Traces" or title="Start DU Traces"]//button'
    _CPLANE_STOP_DU_TRACES_BUTTON_XPATH = '//cplane//ui-button' \
                                          '[@a-text="Stop DU Traces" or title="Stop DU Traces"]//button'
    _CPLANE_TRACE_STATUS_XPATH = '//cplane//*[contains(@class, "test-setup-control-second-container-info")]' \
                                 '//span[not(contains(@class, "icon"))]'

    _ACTIVATE_INTERNAL_TRACE_BUTTON = '//log-agent-configuration//*[@a-text="Activate"]/button'
    _DEACTIVATE_INTERNAL_TRACE_BUTTON = '//log-agent-configuration//*[@a-text="Deactivate"]/button'
    _INTERNAL_TRACE_STATUS_XPATH = '//log-agent-configuration//*[contains(@class, ' \
                                   '"test-setup-control-second-container-active")]//span[not(contains(@class, "icon"))]'
    _TRACE_SENDING_STATUS = 'Sending...'

    def _choose_bbmod(self, bbmod):
        self.select_element_from_dropdown_list_by_text_and_click(bbmod,
                                                                 (By.XPATH, self._BBMOD_DROPDOWN_BUTTON_XPATH),
                                                                 (By.XPATH, self._BBMOD_DROPDOWN_LIST_XPATH))

    def _choose_operation(self, module_type, operation):
        """
        This method is used to chose radio box under UPlane Component and Sherpa
        :param module_type: str
        :param operation: str
        """
        mapping_table = {
            self._COMPONENT_TYPE: {
                self._CONFIGURE: self._CONFIGURE_OPERATION_XPATH,
                self._SAVE_IQ: self._SAVE_IQ_OPERATION_XPATH,
                self._PDCP: self._PDCP_RADIO_BOX_XPATH,
                self._RLC: self._RLC_RADIO_BOX_XPATH
            },
            self._SHERPA_TYPE: {
                self._PDCP: self._SHERPA_PDCP_RADIO_BOX_XPATH,
                self._RLC: self._SHERPA_RLC_RADIO_BOX_XPATH
            }
        }
        self.select_radiobox_by_xpath(mapping_table[module_type][operation])

    def _input_subcell_index_and_other_fields(self, filed_name, value):
        self.insert_text_to_enable_element((By.XPATH, self._L1_IQ_FIELDS_BASE_XPATH.format(filed_name)), value)

    def configure_iq_capture(self, bbmod, ul_subcell_index, dl_subcell_index, enable_capture_on_event):
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_bbmod(bbmod)
        self._choose_operation(self._COMPONENT_TYPE, self._CONFIGURE)
        self._input_subcell_index_and_other_fields(self._UL_SUBCELL, ul_subcell_index)
        self._input_subcell_index_and_other_fields(self._DL_SUBCELL, dl_subcell_index)
        self.select_checkbox_by_specified_status(enable_capture_on_event,
                                                 self._CAPTURE_EVENT_INPUT_XPATH,
                                                 self._CAPTURE_EVENT_CHECKOUT_XPATH)
        self.click_enabled_element((By.XPATH, self._APPLY_CONFIGURATION_BUTTON_XPATH))

    def save_iq_capture(self, bbmod, sfn_value, slot_value):
        """
        Keyword for saving iq capture
        :param bbmod: str, bbmod
        :param sfn_value: int, value of sfn
        :param slot_value: int, value of slot
        """
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_bbmod(bbmod)
        self._choose_operation(self._COMPONENT_TYPE, self._SAVE_IQ)
        self._input_subcell_index_and_other_fields(self._SFN, sfn_value)
        self._input_subcell_index_and_other_fields(self._SLOT, slot_value)
        self.click_enabled_element((By.XPATH, self._SAVE_IQ_CAPTURE_DATA_BUTTON_XPATH))

    def _input_cplan_or_uplan_ip_address(self, destination_address, destination_xpath):
        for index, elem in enumerate(self.driver.find_elements_by_xpath(destination_xpath)):
            self._insert_text_to_field(destination_address.rsplit(":", 1)[index], elem)

    def configure_logging_agent(self, source_ip=None, vlan=None, dscp=None,
                                cplane_destination=None, uplane_destination=None, timeout=60):
        if source_ip:
            self.insert_text_to_enable_element((By.XPATH, self._LOGGING_AGENT_SOURCE_IP_XPATH), source_ip, timeout)
        if vlan:
            self.insert_text_to_enable_element((By.XPATH, self._LOGGING_AGENT_VLAN_XPATH), vlan)
        if dscp:
            self.insert_text_to_enable_element((By.XPATH, self._LOGGING_AGENT_DSCP_XPATH), dscp)
        if cplane_destination:
            self._input_cplan_or_uplan_ip_address(cplane_destination, self._LOGGING_CPLANE_IP_XPATH)
        if uplane_destination:
            self._input_cplan_or_uplan_ip_address(uplane_destination, self._LOGGING_UPLANE_IP_XPATH)

    def _return_error_if_configure_modal_exist(self):
        invalid_agent_configuration_modal = InvalidAgentConfigurationModal()
        return invalid_agent_configuration_modal.wait_until_invalid_modal_appear_and_return_modal_info(2)

    def _get_trace_status_after_start_or_stop(self, trace_status_xpath, tracing_middle_status, timeout):
        self.wait_for_text_not_present_in_element((By.XPATH, trace_status_xpath),
                                                  tracing_middle_status,
                                                  timeout)
        return self.get_text_by_xpath(trace_status_xpath)

    def _get_tracing_result(self, module_type, timeout=60):
        error_info = self._return_error_if_configure_modal_exist()
        if error_info:
            return error_info

        module_type_mapping_dict = {
            self._COMPONENT_TYPE: self._COMPONENT_TRACE_STATUS_XPATH,
            self._SHERPA_TYPE: self._SHERPA_TRACE_STATUS_XPATH,
            self._CPLANE_TYPE: self._CPLANE_TRACE_STATUS_XPATH
        }
        return self._get_trace_status_after_start_or_stop(module_type_mapping_dict[module_type],
                                                          self._TRACE_STARTING_STATUS,
                                                          timeout)

    def _choose_cells(self, cells_list, module_type, timeout=60):
        for index, cell_text in enumerate(cells_list):
            self.select_element_from_dropdown_list_by_text_and_click(
                cell_text,
                (By.XPATH, self._CELLS_BUTTON_XPATH.format(module_type, index + 1)),
                (By.XPATH, self._CELLS_OPTION_XPATH.format(module_type, index + 1)),
                timeout
            )

    def start_l2_hi_pdcp_component_trace_and_return_result(self, timeout=60):
        """
        Keyword for starting l2 hi pdcp trace and get result after starting
        :param timeout: int, timeout
        :return: str
        """
        self.click_enabled_element((By.XPATH, self._L2_HI_XPATH), timeout)
        self._choose_operation(self._COMPONENT_TYPE, self._PDCP)
        self.click_enabled_element((By.XPATH, self._START_TRACE_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._COMPONENT_TYPE, timeout)

    def start_l2_hi_rlc_component_trace_and_return_result(self, cells_list, timeout=60):
        """
        Keyword for starting l2 hi rlc trace and get result after starting
        :param cells_list: list, list of cells
        :param timeout: int, timeout
        :return: str
        """
        self.click_enabled_element((By.XPATH, self._L2_HI_XPATH), timeout)
        self._choose_operation(self._COMPONENT_TYPE, self._RLC)
        self._choose_cells(cells_list, self._UPLANE_COMPONENT_LABEL, timeout)
        self.click_enabled_element((By.XPATH, self._START_TRACE_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._COMPONENT_TYPE, timeout)

    def start_l2_lo_component_trace_and_return_result(self, cells_list, timeout=60):
        """
        Keyword for starting l2 lo trace and get result after starting
        :param cells_list: list, list of cells
        :param timeout: int, timeout
        :return: str
        """
        self.click_enabled_element((By.XPATH, self._L2_LO_XPATH), timeout)
        self._choose_cells(cells_list, self._UPLANE_COMPONENT_LABEL, timeout)
        self.click_enabled_element((By.XPATH, self._START_TRACE_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._COMPONENT_TYPE, timeout)

    def start_l2_ps_component_trace_and_return_result(self, cells_list, timeout=60):
        """
        Keyword for starting l2 ps trace and get result after starting
        :param cells_list: list, list of cells
        :param timeout: int, timeout
        :return: str
        """
        self.click_enabled_element((By.XPATH, self._L2_PS_XPATH), timeout)
        self._choose_cells(cells_list, self._UPLANE_COMPONENT_LABEL, timeout)
        self.click_enabled_element((By.XPATH, self._START_TRACE_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._COMPONENT_TYPE, timeout)

    def stop_component_trace(self, uplane_component_name, source=None, timeout=60):
        """
        Keyword for stopping trace
        :param uplane_component_name: str, name of uplane module
        :param source: str, "PDCP" or "RLC" can be passed in when uplane_module_name is L2-HI
        :param timeout: int, timeout
        :return: str
        """
        self.click_enabled_element((By.XPATH, self._UPLANE_COMPONENT_BASE_XPATH.format(uplane_component_name)), timeout)
        if source:
            self._choose_operation(self._COMPONENT_TYPE, source)
        self.click_enabled_element((By.XPATH, self._STOP_TRACE_BUTTON_XPATH), timeout)
        return self._get_trace_status_after_start_or_stop(self._COMPONENT_TRACE_STATUS_XPATH,
                                                          self._TRACE_STOP_STATUS,
                                                          timeout)

    def start_l2_hi_pdcp_sherpa_trace_and_return_result(self, timeout=60):
        """
        Keyword for starting l2 hi pdcp sherpa trace and get result after starting

        :param timeout: int, timeout
        :return: str
        """
        self.click_enabled_element((By.XPATH, self._SHERPA_L2_HI_XPATH), timeout)
        self._choose_operation(self._SHERPA_TYPE, self._PDCP)
        self.click_enabled_element((By.XPATH, self._SHERPA_START_TRACES_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._SHERPA_TYPE, timeout)

    def _choose_cells_if_version_above_5G19(self, cells_list, module_type, timeout=60):
        """
        Method for choosing cells if bts version is above 5G19
        """
        if '5G19' not in BtsBasicInfo().get_bts_version():
            self._choose_cells(cells_list, module_type, timeout)

    def start_l2_hi_rlc_sherpa_trace_and_return_result(self, cells_list, timeout=60):
        """
        Keyword for starting l2 hi rlc sherpa trace and get result after starting

        :param cells_list: list, list of cells
        :param timeout: int, timeout
        :return: trace result
        :rtype: str
        """
        self.click_enabled_element((By.XPATH, self._SHERPA_L2_HI_XPATH), timeout)
        self._choose_operation(self._SHERPA_TYPE, self._RLC)
        self._choose_cells_if_version_above_5G19(cells_list, self._UPLANE_SHERPA_LABEL, timeout)
        self.click_enabled_element((By.XPATH, self._SHERPA_START_TRACES_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._SHERPA_TYPE, timeout)

    def start_l2_lo_sherpa_trace_and_return_result(self, cells_list, timeout=60):
        """
        Keyword for starting l2 lo sherpa trace and get result after starting

        :param cells_list: list, list of cells
        :param timeout: int, timeout
        :return: trace result
        :rtype: str
        """
        self.click_enabled_element((By.XPATH, self._SHERPA_L2_LO_XPATH), timeout)
        self._choose_cells_if_version_above_5G19(cells_list, self._UPLANE_SHERPA_LABEL, timeout)
        self.click_enabled_element((By.XPATH, self._SHERPA_START_TRACES_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._SHERPA_TYPE, timeout)

    def start_l2_ps_sherpa_trace_and_return_result(self, cells_list, timeout=60):
        """
        Keyword for starting l2 ps sherpa trace and get result after starting

        :param cells_list: list, list of cells
        :param timeout: int, timeout
        :return: trace result
        :rtype: str
        """
        self.click_enabled_element((By.XPATH, self._SHERPA_L2_PS_XPATH), timeout)
        self._choose_cells_if_version_above_5G19(cells_list, self._UPLANE_SHERPA_LABEL, timeout)
        self.click_enabled_element((By.XPATH, self._SHERPA_START_TRACES_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._SHERPA_TYPE, timeout)

    def stop_sherpa_trace(self, sherpa_module_name, source=None, timeout=60):
        """
        Keyword for stopping sherpa trace
        :param sherpa_module_name: str, name of uplane sherpa module, "L2-HI", "L2-LO" and "L2-PS" can be passed in
        :param source: str, "PDCP" or "RLC" can be passed in when uplane_sherpa_name is L2-HI
        :param timeout: int, timeout
        :return: str
        """
        self.click_enabled_element((By.XPATH, self._UPLANE_SHERPA_BASE_XPATH.format(sherpa_module_name)), timeout)
        if source:
            self._choose_operation(self._SHERPA_TYPE, source)
        self.click_enabled_element((By.XPATH, self._SHERPA_STOP_TRACES_BUTTON_XPATH), timeout)
        return self._get_trace_status_after_start_or_stop(self._SHERPA_TRACE_STATUS_XPATH,
                                                          self._TRACE_STOP_STATUS,
                                                          timeout)

    def start_cplane_du_traces(self, timeout=60):
        """
        Method for starting cplane du traces
        """
        self.click_enabled_element((By.XPATH, self._CPLANE_START_DU_TRACES_BUTTON_XPATH), timeout)
        return self._get_tracing_result(self._CPLANE_TYPE, timeout)

    def stop_cplane_du_traces(self, timeout=60):
        """
        Method for stopping cplane du traces
        """
        self.click_enabled_element((By.XPATH, self._CPLANE_STOP_DU_TRACES_BUTTON_XPATH), timeout)
        return self._get_trace_status_after_start_or_stop(self._CPLANE_TRACE_STATUS_XPATH,
                                                          self._TRACE_STOP_STATUS,
                                                          timeout)

    def activate_internal_trace(self, timeout):
        """
        Method for activate internal trace
        """
        try:
            self.click_enabled_element((By.XPATH, self._ACTIVATE_INTERNAL_TRACE_BUTTON), 10)
            return self._get_trace_status_after_start_or_stop(self._INTERNAL_TRACE_STATUS_XPATH,
                                                              self._TRACE_SENDING_STATUS,
                                                              timeout)
        except TimeoutException:
            raise ButtonCanNotClick('Activate button is disable, can not be clicked.')

    def deactivate_internal_trace(self, timeout):
        """
        Method for deactivate internal trace
        """
        try:
            self.click_enabled_element((By.XPATH, self._DEACTIVATE_INTERNAL_TRACE_BUTTON), 10)
            return self._get_trace_status_after_start_or_stop(self._INTERNAL_TRACE_STATUS_XPATH,
                                                              self._TRACE_SENDING_STATUS,
                                                              timeout)
        except TimeoutException:
            raise ButtonCanNotClick('DeActivate button is disable, can not be clicked.')
